// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.undoimport timber.log.Timberimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategoryimport com.roshan.persona.system.executor.SystemOperationClassifierimport com.roshan.persona.system.executor.SystemOperationExecutorImplimport com.roshan.persona.system.handler.SystemOperationHandlerimport kotlinx.coroutines.asyncimport kotlinx.coroutines.awaitAllimport kotlinx.coroutines.coroutineScopeimport kotlinx.coroutines.launchimport kotlinx.coroutines.sync.Muteximport kotlinx.coroutines.sync.withLock/** * NOUS — Atomic Batch Coordinator (Module 10 v2 — Review 1 + Review 2 merge). * * Executes a batch of [SystemOperation]s with **all-or-nothing** semantics: * if any operation fails, all previously-executed operations are rolled back * to their pre-state. This prevents the device from being left in an * inconsistent state (e.g., torch on but volume not set). * * ## Parallel vs Sequential Dispatch (per strategy §"Compound Intent Dispatch") * * Operations are grouped by [ResourceCategory]: *  - **Different categories** → run in **parallel** (no resource contention). *    Example: DnD (AUDIO) + Alarm (SETTINGS) + Lock (DISPLAY) → 3 parallel *    coroutines → ~100 ms total (not 300 ms sequential). * *  - **Same category** → run **sequentially** within that group (avoid race *    conditions like two `AudioManager.adjustVolume` calls stomping each other). *    Example: Volume up × 3 → 1 AUDIO group → sequential → 3 × 30 ms = 90 ms. * * ## Rollback (per strategy §"Atomic Batch Execution") * * On any failure: *  1. Stop executing remaining operations. *  2. For each already-executed operation (in reverse order), call *     `handler.restorePreState(operation, preState)`. *  3. Return [Result.Failure] with the failure reason + rollback summary. * * Pre-states are captured BEFORE execution (per Review 2 Fix A — pre-state, * NOT inverse). This means rollback restores the actual previous value, not * the inverse operation. If the user manually changed state between NOUS's * action and the rollback, the pre-state is still correct (it's what NOUS * observed before acting). * * ## Wiring * * Called by [SystemOperationExecutorImpl.executeAll] (replacing the v1 * sequential stop-on-failure behavior). The executor's `execute` method * remains the single-operation entry point — the coordinator just orchestrates * multiple `execute` calls with pre-state tracking + rollback. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Architecture — Atomic Batch Execution</a> */class AtomicBatchCoordinator(    private val executor: SystemOperationExecutorImpl,    private val handlers: Map<Class<out SystemOperation>, SystemOperationHandler<*>>,) {    /**     * Execute a batch of operations atomically.     *     * @param operations the operations to execute (order matters within a category).     * @return [Result.Success] with per-operation results if all succeeded,     *         or [Result.Failure] if any failed (with rollback applied).     */    @Suppress("UNCHECKED_CAST")    suspend fun executeAll(operations: List<SystemOperation>): Result<List<Result<Unit>>> {        val startNanos = System.nanoTime()        val correlationId = CorrelationId.generate()        if (operations.isEmpty()) {            return Result.Success(emptyList(), correlationId, System.nanoTime() - startNanos)        }        // Track executed operations + their pre-states for rollback.        val executedWithPreStates = mutableListOf<Pair<SystemOperation, Any?>>()        val perOpResults = mutableListOf<Result<Unit>>()        val rollbackMutex = Mutex()  // serialize rollback writes        // Group by resource category for parallel/sequential decision.        val groups = SystemOperationClassifier.groupByCategory(operations)            .filterKeys { it != ResourceCategory.SPECIAL }        try {            coroutineScope {                // Launch one coroutine per resource category — parallel across categories.                val categoryJobs = groups.map { (category, ops) ->                    async {                        for (op in ops) {  // sequential within category                            // Capture pre-state before execution.                            val preState = capturePreStateFor(op)                            // Execute via the single-op executor.                            val result = executor.execute(op)                            // Record result + pre-state (under mutex — parallel categories                            // may complete in any order).                            rollbackMutex.withLock {                                perOpResults.add(result)                                if (result is Result.Success) {                                    executedWithPreStates.add(op to preState)                                }                            }                            // On failure, throw to trigger rollback.                            if (result is Result.Failure) {                                throw BatchFailedException(op, result.error)                            }                        }                    }                }                categoryJobs.awaitAll()            }            // All operations succeeded.            return Result.Success(                data = perOpResults,                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        } catch (e: BatchFailedException) {            // ROLLBACK: restore pre-states in reverse order.            Timber.tag(TAG).w("Batch failed at ${e.failedOp::class.simpleName}: ${e.error}. " +                "Rolling back ${executedWithPreStates.size} operations.")            val rollbackResults = rollback(executedWithPreStates.reversed())            return Result.Failure(                error = AppError.Hardware.Unknown(                    resource = e.failedOp::class.simpleName ?: "batch",                    cause = e,                ),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        } catch (t: Throwable) {            // Unexpected error — rollback everything executed so far.            Timber.tag(TAG).e("Batch crashed unexpectedly", t)            rollback(executedWithPreStates.reversed())            return Result.Failure(                error = AppError.from(t, correlationId),                correlationId = correlationId,                durationNanos = System.nanoTime() - startNanos,            )        }    }    // ──────────────────────────────────────────────────────────────────────    /** Capture the pre-state for [operation] via its handler. */    @Suppress("UNCHECKED_CAST")    private suspend fun capturePreStateFor(operation: SystemOperation): Any? {        val handler = findHandler(operation) ?: return null        val typedHandler = handler as SystemOperationHandler<SystemOperation>        return try {            typedHandler.capturePreState(operation)        } catch (t: Throwable) {            Timber.tag(TAG).w("Pre-state capture failed for ${operation::class.simpleName}", t)            null        }    }    /** Restore pre-states for a list of (operation, preState) pairs. */    @Suppress("UNCHECKED_CAST")    private suspend fun rollback(        toRestore: List<Pair<SystemOperation, Any?>>,    ): List<Result<Unit>> {        val results = mutableListOf<Result<Unit>>()        for ((operation, preState) in toRestore) {            val handler = findHandler(operation)            if (handler == null) {                results.add(Result.Failure(                    AppError.Hardware.Unsupported(operation::class.simpleName ?: "unknown"),                    CorrelationId.generate(), 0,                ))                continue            }            val typedHandler = handler as SystemOperationHandler<SystemOperation>            val restoreResult = try {                typedHandler.restorePreState(operation, preState)                Result.Success(Unit, CorrelationId.generate(), 0)            } catch (t: Throwable) {                Timber.tag(TAG).w("Rollback failed for ${operation::class.simpleName}", t)                Result.Failure(                    AppError.Hardware.Unknown(operation::class.simpleName ?: "unknown", t),                    CorrelationId.generate(), 0,                )            }            results.add(restoreResult)        }        return results    }    /** Find the handler registered for [operation]'s type. */    private fun findHandler(operation: SystemOperation): SystemOperationHandler<*>? {        handlers[operation::class.java]?.let { return it }        for ((cls, handler) in handlers) {            if (cls.isAssignableFrom(operation::class.java)) return handler        }        return null    }    /** Internal exception used to trigger rollback via coroutine cancellation. */    private class BatchFailedException(        val failedOp: SystemOperation,        val error: AppError,    ) : RuntimeException("Batch failed at ${failedOp::class.simpleName}: $error")    private companion object {        private const val TAG = "AtomicBatch"    }}